package com.lamggm.rospocket;
import android.content.Context;
import android.graphics.drawable.GradientDrawable;
import android.widget.*;
import android.text.TextUtils;
import java.util.*;
import java.util.function.Consumer;

final class RobotPanel extends LinearLayout {
 final RobotModelView view;private final TextView status,source;private final Button choose,missing;private final RobotContext context;private final Consumer<String> title;
 private final TextView poseStatus;private Button tfButton;private boolean tfEnabled;private RobotContext.PoseSnapshot lastPose;
 private android.app.Dialog fullscreen;private TextView fullStatus;
 private LinearLayout tileDetails;private android.app.AlertDialog tileDialog;
 private RobotDescription shown;private RobotAssetBundle assets;private final RobotAssetsPanel assetControl;private String renderFailure="";private List<RobotContext.Source> sources=Collections.emptyList();private RobotContext.Snapshot displayed;
 RobotPanel(Context c,RobotContext owner,Consumer<String> name){super(c);context=owner;title=name;setOrientation(VERTICAL);setTag("design-surface");setPadding(dp(18),dp(14),dp(18),dp(14));GradientDrawable shape=new GradientDrawable();shape.setColor(UiTheme.color(c,0xff161d27));shape.setCornerRadius(dp(12));setBackground(shape);
  TextView heading=text("ROBÔ 3D",13);addView(heading);status=text("Aguardando tópico robot_description existente",13);status.setTag("robot-status");addView(status);source=text("",11);addView(source);
  view=new RobotModelView(c);view.setTag("robot-model");LayoutParams image=new LayoutParams(-1,dp(230));image.topMargin=dp(8);image.bottomMargin=dp(8);addView(view,image);
  LinearLayout actions=new LinearLayout(c);actions.setBaselineAligned(false);CheckBox spin=new CheckBox(c);spin.setText("Giro automático");spin.setChecked(true);spin.setMinHeight(dp(48));spin.setTag("robot-spin");spin.setOnCheckedChangeListener((b,on)->view.setAutoRotate(on));actions.addView(spin,new LayoutParams(0,-2,1));Button reset=new VisualButton(c,"secondary",null);reset.setText("Recentrar");reset.setTag("robot-reset");reset.setOnClickListener(v->view.resetView());actions.addView(reset,new LayoutParams(0,dp(48),1));addView(actions);
  Button expand=new VisualButton(c,"secondary",null);expand.setText("Tela cheia ↗");expand.setTag("robot-fullscreen");expand.setOnClickListener(v->openFullscreen());addView(expand,new LayoutParams(-1,dp(48)));
  choose=new VisualButton(c,"secondary",null);choose.setTag("robot-source");choose.setText("Escolher descrição");choose.setOnClickListener(v->chooseSource());addView(choose,new LayoutParams(-1,dp(48)));
  missing=new VisualButton(c,"secondary",null);missing.setText("Malhas ausentes");missing.setOnClickListener(v->{if(shown==null)return;android.app.AlertDialog d=new android.app.AlertDialog.Builder(c).setTitle("Malhas não recebidas").setItems(absent().toArray(new String[0]),null).setPositiveButton("Fechar",null).create();d.show();UiTheme.dialog(d);});missing.setVisibility(GONE);addView(missing,new LayoutParams(-1,dp(48)));
  assetControl=new RobotAssetsPanel((android.app.Activity)c,()->shown,value->{assets=value;rebuild();refreshStatus();applyPose();});addView(assetControl);
  view.setFailureListener(message->{renderFailure="Visualização indisponível: "+message;refreshStatus();});
  tfButton=new VisualButton(c,"secondary",null);tfButton.setTag("robot-tf-mode");tfButton.setText("Usar TF observado");tfButton.setOnClickListener(v->{tfEnabled=!tfEnabled;applyPose();});addView(tfButton,new LayoutParams(-1,dp(48)));poseStatus=text("Pose de referência URDF · sem TF/joint_states. O giro é apenas visual.",11);poseStatus.setTag("robot-pose-status");addView(poseStatus);
 }
 void tileMode(){
  if(tileDetails!=null)return;android.view.View heading=getChildAt(0),actions=(android.view.View)((android.view.View)findViewWithTag("robot-spin")).getParent();Button expand=findViewWithTag("robot-fullscreen");removeView(heading);removeView(expand);
  LinearLayout bar=new LinearLayout(getContext());bar.setGravity(android.view.Gravity.CENTER_VERTICAL);bar.addView(heading,new LayoutParams(0,-2,1));Button options=new VisualButton(getContext(),"icon","more");options.setContentDescription("Descrição, malhas e modo TF do modelo");options.setTag("robot-options");options.setOnClickListener(v->openTileOptions());bar.addView(options,new LayoutParams(dp(48),dp(48)));expand.setText("↗");expand.setContentDescription("Tela cheia do modelo 3D");bar.addView(expand,new LayoutParams(dp(48),dp(48)));addView(bar,0,new LayoutParams(-1,-2));
  tileDetails=new LinearLayout(getContext());tileDetails.setOrientation(VERTICAL);List<android.view.View> move=new ArrayList<>();for(int i=1;i<getChildCount();i++){android.view.View child=getChildAt(i);if(child!=status&&child!=view&&child!=actions&&child!=poseStatus)move.add(child);}for(android.view.View child:move){android.view.ViewGroup.LayoutParams lp=child.getLayoutParams();removeView(child);tileDetails.addView(child,lp);}tileDetails.setVisibility(GONE);addView(tileDetails);
  status.setMaxLines(2);status.setEllipsize(TextUtils.TruncateAt.END);poseStatus.setMaxLines(2);poseStatus.setEllipsize(TextUtils.TruncateAt.END);LayoutParams image=new LayoutParams(-1,0,1);image.topMargin=dp(8);image.bottomMargin=dp(8);view.setLayoutParams(image);
 }
 private void openTileOptions(){if(tileDetails==null||tileDialog!=null)return;android.app.Activity owner=(android.app.Activity)getContext();if(owner.isFinishing()||owner.isDestroyed())return;removeView(tileDetails);tileDetails.setVisibility(VISIBLE);ScrollView scroll=new ScrollView(getContext());scroll.addView(tileDetails);android.app.AlertDialog d=new android.app.AlertDialog.Builder(getContext()).setTitle("Modelo 3D · Descrição e TF").setView(scroll).setPositiveButton("Fechar",null).create();tileDialog=d;d.setOnDismissListener(ignored->{scroll.removeView(tileDetails);tileDetails.setVisibility(GONE);addView(tileDetails);tileDialog=null;});d.show();UiTheme.dialog(d);}
 void appearance(){if(tileDialog!=null&&tileDialog.isShowing())UiTheme.dialog(tileDialog);}
 private void closeTileOptions(){if(tileDialog!=null)tileDialog.dismiss();}
 private void openFullscreen(){
  if(fullscreen!=null)return;android.app.Activity activity=(android.app.Activity)getContext();if(activity.isFinishing()||activity.isDestroyed())return;
  final int index=indexOfChild(view);final android.view.ViewGroup.LayoutParams original=view.getLayoutParams();android.view.View spacer=new android.view.View(getContext());removeView(view);addView(spacer,index,original);
  android.app.Dialog d=new android.app.Dialog(getContext());d.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);fullscreen=d;LinearLayout body=new LinearLayout(getContext());body.setOrientation(VERTICAL);body.setPadding(dp(12),dp(8),dp(12),dp(8));body.setBackgroundColor(VisualButton.bg(getContext()));fullStatus=text(status.getText().toString(),13);body.addView(fullStatus);body.addView(view,new LayoutParams(-1,0,1));
  LinearLayout bar=new LinearLayout(getContext());bar.setBaselineAligned(false);Button exit=new VisualButton(getContext(),"secondary",null);exit.setText("Voltar ao painel");exit.setTag("robot-exit-fullscreen");exit.setOnClickListener(v->d.dismiss());bar.addView(exit,new LayoutParams(0,dp(48),1));Button reset=new VisualButton(getContext(),"secondary",null);reset.setText("Recentrar");reset.setTag("robot-full-reset");reset.setOnClickListener(v->view.resetView());bar.addView(reset,new LayoutParams(0,dp(48),1));CheckBox spin=new CheckBox(getContext());spin.setText("Giro");spin.setChecked(view.autoRotate);spin.setMinHeight(dp(48));spin.setOnCheckedChangeListener((b,on)->((CheckBox)findViewWithTag("robot-spin")).setChecked(on));bar.addView(spin,new LayoutParams(0,dp(48),1));body.addView(bar);
  d.setContentView(body);d.setOnDismissListener(dialog->{if(view.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)view.getParent()).removeView(view);int at=indexOfChild(spacer);removeView(spacer);addView(view,Math.max(0,at),original);fullscreen=null;fullStatus=null;});d.show();android.view.Window w=d.getWindow();if(w!=null){w.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(VisualButton.bg(getContext())));w.setLayout(-1,-1);w.setFlags(android.view.WindowManager.LayoutParams.FLAG_FULLSCREEN,android.view.WindowManager.LayoutParams.FLAG_FULLSCREEN);w.getDecorView().setSystemUiVisibility(android.view.View.SYSTEM_UI_FLAG_FULLSCREEN|android.view.View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|android.view.View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);}
 }
 void invalidatePose(){lastPose=null;applyPose();}
 void updatePose(RobotContext.PoseSnapshot p){if(!context.current(p)||shown==null||!shown.fingerprint.equals(p.fingerprint))return;if(lastPose!=null&&lastPose.pose.revision==p.pose.revision&&lastPose.pose.live==p.pose.live&&lastPose.pose.status.equals(p.pose.status))return;lastPose=p;applyPose();}
 private void applyPose(){boolean full=assets!=null&&assets.fullGeometry()&&assets.matches(shown);tfButton.setEnabled(full);if(!full&&tfEnabled)tfEnabled=false;tfButton.setText(tfEnabled?"Usar pose URDF de referência":"Usar TF observado");RobotTf.Pose p=lastPose==null?null:lastPose.pose;if(tfEnabled){view.setTransforms(p!=null&&p.live?p.transforms:Collections.emptyMap());textIfChanged(poseStatus,p==null?"Aguardando TF observado":p.live?"TF observado · frame fixo "+shown.rootLink+" · "+lastPose.source:p.status);}else{view.setTransforms(null);textIfChanged(poseStatus,shown==null?"Sem descrição atual · TF inativo":"Pose de referência URDF · não é pose atual do robô. Giro apenas visual.");}if(fullStatus!=null)textIfChanged(fullStatus,status.getText()+" · "+poseStatus.getText());}
 private void closeFullscreen(){if(fullscreen!=null)fullscreen.dismiss();}
 private TextView text(String value,int sp){TextView t=new TextView(getContext());t.setText(value);t.setTextSize(sp);t.setTextColor(VisualButton.muted(getContext()));return t;}
 private void textIfChanged(TextView v,String s){if(!TextUtils.equals(v.getText(),s))v.setText(s);}
 private void chooseSource(){if(sources.isEmpty())return;final RobotContext.Snapshot opened=displayed;List<RobotContext.Source> copy=new ArrayList<>(sources);String[] names=new String[copy.size()+1];names[0]="Automático (somente uma descrição)";for(int i=0;i<copy.size();i++)names[i+1]=copy.get(i).name;android.app.AlertDialog d=new android.app.AlertDialog.Builder(getContext()).setTitle("Descrição do robô · somente leitura").setItems(names,(dialog,index)->{if(!context.current(opened)||displayed==null)return;context.select(index==0?"":copy.get(index-1).wire);clear("Aguardando descrição selecionada");}).setNegativeButton("Cancelar",null).create();d.show();UiTheme.dialog(d);}
 private List<String> absent(){List<String> list=new ArrayList<>();if(shown!=null)for(String uri:shown.missingMeshes)if(assets==null||!assets.matches(shown)||!assets.hasMesh(uri))list.add(uri);return list;}
 private void rebuild(){renderFailure="";try{view.setModel(shown,assets);}catch(IllegalArgumentException e){view.setModel(null);renderFailure="Visualização indisponível: "+e.getMessage();}}
 private void refreshStatus(){if(displayed!=null){String value=displayed.status;if(shown!=null&&assets!=null&&assets.matches(shown)&&!shown.missingMeshes.isEmpty()){int n=absent().size();value=value.replace("Modelo parcial · "+shown.missingMeshes.size()+" malha(s) não recebida(s)",n==0?assets.fullGeometry()?"CAD indexado completo · "+view.geometryFaces()+" faces":"Modelo completo · malhas locais otimizadas":"Modelo parcial · "+n+" malha(s) não recebida(s)");}textIfChanged(status,renderFailure.isEmpty()?value:renderFailure);}missing.setVisibility(absent().isEmpty()?GONE:VISIBLE);if(fullStatus!=null)textIfChanged(fullStatus,status.getText()+" · "+poseStatus.getText());}
 void update(RobotContext.Snapshot snapshot){if(!context.current(snapshot))return;displayed=snapshot;sources=snapshot.sources;choose.setEnabled(!sources.isEmpty());textIfChanged(source,snapshot.source);RobotDescription next=snapshot.model;title.accept(next==null?"Seu painel":next.name);if(shown!=next){boolean geometryChanged=shown==null||next==null||!shown.fingerprint.equals(next.fingerprint);shown=next;if(geometryChanged){lastPose=null;rebuild();applyPose();}}assetControl.setCanImport(next!=null);refreshStatus();}
 void clear(String reason){closeTileOptions();closeFullscreen();lastPose=null;tfEnabled=false;displayed=null;renderFailure="";sources=Collections.emptyList();shown=null;view.setModel(null);title.accept("Seu painel");textIfChanged(status,reason);textIfChanged(source,"");choose.setEnabled(false);missing.setVisibility(GONE);assetControl.setCanImport(false);applyPose();}
 boolean result(int request,int code,android.content.Intent data){return assetControl.result(request,code,data);}
 void dispose(){closeTileOptions();closeFullscreen();assetControl.dispose();view.setScreenActive(false);view.releaseRaster();}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
}
